package com.vandorlabs.neoforge.copifier;
import com.google.gson.*;
import com.vandorlabs.neoforge.storage.*;
import java.nio.file.*;
import java.util.*;
import java.util.zip.GZIPInputStream;
import net.minecraft.core.*;
import net.minecraft.nbt.*;
import net.minecraft.server.level.*;
import net.minecraft.world.level.GameType;
import net.minecraft.world.level.block.Blocks;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.neoforge.event.server.ServerStartedEvent;
/** Source copy semantics with live inventory, same owner, settings-only undo and bounded reads. */
@EventBusSubscriber(modid="vandorlabs")
public final class NativeCopifierStorageWorldChecks {
 private static final BlockPos POS=new BlockPos(15600,100,14640);private static int checks;
 private static void need(boolean yes,String why){checks++;if(!yes)throw new AssertionError("Copifier Storage: "+why);}
 private static NativeStorageEntity put(ServerLevel level,int meta,CompoundTag data){level.getChunkAt(POS);level.setBlock(POS,Blocks.AIR.defaultBlockState(),18);level.setBlock(POS,NativeStorageRegistrations.BLOCK.get().legacyState(meta),18);var tile=(NativeStorageEntity)level.getBlockEntity(POS);var raw=data.copy();raw.putString("UnrelatedStorageMarker","retained");tile.loadWithComponents(raw,level.registryAccess());need(tile.available(),"installed inventory owner");tile.setItem(26,new net.minecraft.world.item.ItemStack(net.minecraft.world.item.Items.DIAMOND,7));return tile;}
 private static void write(ServerLevel level)throws Exception{byte[] raw;try(var in=new GZIPInputStream(Files.newInputStream(Path.of(System.getProperty("vandorlabs.copifierStorageReference"))))){raw=in.readAllBytes();}need(HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(raw)).equals("d04ddbe889a26244478f167737afe4f44baeb935013a8df6e5dca3c76847f3de"),"frozen Source corpus");var actor=new net.neoforged.neoforge.common.util.FakePlayer(level,new com.mojang.authlib.GameProfile(new UUID(0,1879),"CopiedStorage"));actor.setGameMode(GameType.SURVIVAL);actor.setPos(POS.getX()+.5,POS.getY()+1,POS.getZ()-2);int captures=0,cases=0;
  for(var element:JsonParser.parseString(new String(raw,java.nio.charset.StandardCharsets.UTF_8)).getAsJsonArray()){
   var row=element.getAsJsonObject();int meta=row.get("meta").getAsInt();if(row.has("input")){var source=put(level,meta,TagParser.parseTag(row.get("input").getAsString()));var expected=TagParser.parseTag(row.get("capture").getAsString());var actual=NativeCopifierHousingWorld.capture(level,POS,actor,Direction.NORTH);need(expected.equals(actual),"Source capture="+captures+" expected="+expected+" actual="+actual);need(source.getItem(26).getCount()==7,"source inventory unchanged");captures++;}
   var owner=put(level,meta^3,TagParser.parseTag(row.get("target").getAsString()));var state=owner.getBlockState();var before=NativeCopifierHousingWorld.capture(level,POS,actor,Direction.NORTH);var values=TagParser.parseTag(row.get("values").getAsString());var clipboard=values.copy();NativeCopifierUndo.begin(actor,level);boolean applied;try{applied=NativeCopifierHousingWorld.applySingle(level,POS,actor,Direction.NORTH,values);}finally{NativeCopifierUndo.finish(actor);}need(applied==row.get("applied").getAsBoolean(),"Source result case="+cases);var expected=TagParser.parseTag(row.get("after").getAsString());var actual=NativeCopifierHousingWorld.capture(level,POS,actor,Direction.NORTH);need(expected.equals(actual),"Source apply="+cases+" values="+values+" expected="+expected+" actual="+actual);need(level.getBlockEntity(POS)==owner&&owner.getBlockState()==state&&owner.getItem(26).getCount()==7,"owner/orientation/inventory retained");need(owner.saveWithoutMetadata(level.registryAccess()).getString("UnrelatedStorageMarker").equals("retained"),"opaque field retained");need(values.equals(clipboard),"clipboard immutable");
   if(applied&&!before.equals(actual)){owner.setItem(26,new net.minecraft.world.item.ItemStack(net.minecraft.world.item.Items.DIAMOND,11));need(NativeCopifierUndo.undo(actor),"settings-only undo");need(TagParser.parseTag(row.get("undo").getAsString()).equals(NativeCopifierHousingWorld.capture(level,POS,actor,Direction.NORTH))&&owner.getItem(26).getCount()==11,"Source undo projection and subsequent inventory edit case="+cases+" expected="+row.get("undo")+" actual="+NativeCopifierHousingWorld.capture(level,POS,actor,Direction.NORTH)+" count="+owner.getItem(26).getCount());}cases++;
  }
  var owner=put(level,0,new CompoundTag());var peer=POS.east();level.setBlock(peer,NativeStorageRegistrations.BLOCK.get().defaultBlockState().setValue(NativeStorageBlock.FACING,owner.getBlockState().getValue(NativeStorageBlock.FACING)),18);var other=(NativeStorageEntity)level.getBlockEntity(peer);other.loadWithComponents(new CompoundTag(),level.registryAccess());other.setItem(0,new net.minecraft.world.item.ItemStack(net.minecraft.world.item.Items.IRON_INGOT,5));var values=new CompoundTag();values.putInt("wall_texture",7);NativeCopifierUndo.begin(actor,level);int count;try{count=NativeCopifierHousingConnected.apply(level,POS,actor,Direction.NORTH,values,false);}finally{NativeCopifierUndo.finish(actor);}need(count==2,"connected ignores differing inventories count="+count+" origin="+NativeCopifierHousingCapture.connected(NativeCopifierHousingCapture.Family.CUBE,owner.copiedConfiguration(),false)+" peer="+NativeCopifierHousingCapture.connected(NativeCopifierHousingCapture.Family.CUBE,other.copiedConfiguration(),false));need(owner.settings().housing().mainTexture==7&&other.settings().housing().mainTexture==7&&other.getItem(0).getCount()==5,"connected typed appearance");need(NativeCopifierUndo.undo(actor)&&owner.getItem(26).getCount()==7&&other.getItem(0).getCount()==5,"connected undo preserves independent inventories");level.setBlock(peer,Blocks.AIR.defaultBlockState(),18);
  allocation(level,actor);need(NativeCopifierHousingWorld.applySingle(level,POS,actor,Direction.NORTH,values),"saved appearance");System.out.println("[vandorlabs][copifier-storage] write PASS captures="+captures+" cases="+cases+" checks="+checks+" exactSource/typedOwners/independentInventory/undo/connected");
 }
 private static void allocation(ServerLevel level,ServerPlayer actor){var data=new CompoundTag();data.putByteArray("UnrelatedStoragePayload",new byte[65536]);var owner=put(level,0,data);var bean=(com.sun.management.ThreadMXBean)java.lang.management.ManagementFactory.getThreadMXBean();need(bean.isThreadAllocatedMemorySupported(),"thread allocation accounting");bean.setThreadAllocatedMemoryEnabled(true);long id=Thread.currentThread().threadId(),scans=owner.inventoryScans();for(int i=0;i<200;i++){NativeCopifierHousingCapture.capture(NativeCopifierHousingCapture.Family.CUBE,owner.saveWithoutMetadata(level.registryAccess()));NativeCopifierHousingWorld.capture(level,POS,actor,Direction.NORTH);}long start=bean.getThreadAllocatedBytes(id);for(int i=0;i<1000;i++)NativeCopifierHousingCapture.capture(NativeCopifierHousingCapture.Family.CUBE,owner.saveWithoutMetadata(level.registryAccess()));long old=bean.getThreadAllocatedBytes(id)-start;start=bean.getThreadAllocatedBytes(id);for(int i=0;i<1000;i++)NativeCopifierHousingWorld.capture(level,POS,actor,Direction.NORTH);long bounded=bean.getThreadAllocatedBytes(id)-start;need(bounded<old/2&&owner.inventoryScans()==scans,"bounded copy reads omit inventory and opaque payload scans");System.out.println("[vandorlabs][copifier-storage] allocation PASS iterations=1000 oldBytes="+old+" boundedBytes="+bounded);}
 private static void read(ServerLevel level){level.getChunkAt(POS);need(level.getBlockEntity(POS) instanceof NativeStorageEntity,"saved canonical owner");var owner=(NativeStorageEntity)level.getBlockEntity(POS);need(owner.available()&&owner.settings().housing().mainTexture==7&&owner.getItem(26).getCount()==7,"saved settings and inventory");need(owner.saveWithoutMetadata(level.registryAccess()).getByteArray("UnrelatedStoragePayload").length==65536,"opaque payload survives restart");System.out.println("[vandorlabs][copifier-storage] read PASS checks="+checks);}
 @SubscribeEvent public static void started(ServerStartedEvent event){String phase=System.getProperty("vandorlabs.transmitterPhase","");if(!phase.equals("copifier-storage-write")&&!phase.equals("copifier-storage-read"))return;try{if(phase.endsWith("write"))write(event.getServer().overworld());else read(event.getServer().overworld());event.getServer().saveEverything(true,true,true);}catch(Throwable failure){failure.printStackTrace();System.out.println("[vandorlabs][copifier-storage] FAIL "+failure);}finally{event.getServer().halt(false);}}
}
